"""Controlled vocabulary shared by the structure pass, the Director and the delivery layer."""
from __future__ import annotations

import re

EMOTIONS = (
    "neutral", "calm", "joy", "excitement", "tenderness", "sadness", "grief", "fear", "anxiety",
